// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 amount, uint256 depositAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // Keep the deposit large enough to pass MinDeposit and enable a successful deposit.
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        // The cashout must not exceed the deposited balance.
        amount = bound(amount, 0, depositAmount);

        Reverter reverter = new Reverter();
        vm.deal(address(reverter), depositAmount);

        // As the reverter, deposit into c through the payable fallback of Reverter.
        vm.prank(address(reverter));
        bool deposited; try c.Deposit{value: depositAmount}() { deposited = true; } catch { deposited = false; }
        require(deposited, "setup deposit failed");

        uint256 balanceBefore = c.balances(address(reverter));
        uint256 contractBalanceBefore = address(c).balance;

        // The reverter's receive() reverts, so the reference CashOut must revert and roll back.
        vm.prank(address(reverter));
        try c.CashOut(amount) {
            // Mutant reaches this branch without reverting.
        } catch {
            // Reference reaches this branch and rolls back.
        }

        // General rule: a failed Ether transfer must revert and leave c's balance unchanged.
        // Reference satisfies this for every input; the mutant breaks it for any amount > 0.
        assertTrue(
            amount == 0
                ? c.balances(address(reverter)) == balanceBefore && address(c).balance == contractBalanceBefore
                : c.balances(address(reverter)) == balanceBefore && address(c).balance == contractBalanceBefore
        );
    }
}

contract Reverter {
    PrivateBank private c;

    function setC(PrivateBank _c) external {
        c = _c;
    }

    function doDeposit() external payable {
        bool ok; try c.Deposit{value: msg.value}() { ok = true; } catch { ok = false; }
        require(ok, "deposit failed");
    }

    receive() external payable {
        revert("reject ether");
    }
}
